1	/**
2	 * HybridBackend
3	 *
4	 * Combines SQLite for structured queries with AgentDB for vector search.
5	 * Per ADR-009: Hybrid Memory Backend Default.
6	 */
7	
8	import type {
9	  Memory,
10	  MemoryBackend,
11	  MemoryQuery,
12	  MemorySearchResult
13	} from '../../shared/types';
14	import { SQLiteBackend } from './SQLiteBackend';
15	import { AgentDBBackend } from './AgentDBBackend';
16	
17	export class HybridBackend implements MemoryBackend {
18	  private sqliteBackend: SQLiteBackend;
19	  private agentDbBackend: AgentDBBackend;
20	  private initialized: boolean = false;
21	
22	  constructor(sqliteBackend: SQLiteBackend, agentDbBackend: AgentDBBackend) {
23	    this.sqliteBackend = sqliteBackend;
24	    this.agentDbBackend = agentDbBackend;
25	  }
26	
27	  /**
28	   * Initialize both backends
29	   */
30	  async initialize(): Promise<void> {
31	    if (this.initialized) return;
32	
33	    await Promise.all([
34	      this.sqliteBackend.initialize(),
35	      this.agentDbBackend.initialize()
36	    ]);
37	
38	    this.initialized = true;
39	  }
40	
41	  /**
42	   * Close both backends
43	   */
44	  async close(): Promise<void> {
45	    await Promise.all([
46	      this.sqliteBackend.close(),
47	      this.agentDbBackend.close()
48	    ]);
49	    this.initialized = false;
50	  }
51	
52	  /**
53	   * Store memory in both backends
54	   */
55	  async store(memory: Memory): Promise<Memory> {
56	    // Store in SQLite for structured queries
57	    await this.sqliteBackend.store(memory);
58	
59	    // Store in AgentDB if has embedding
60	    if (memory.embedding && memory.embedding.length > 0) {
61	      await this.agentDbBackend.store(memory);
62	    }
63	
64	    return memory;
65	  }
66	
67	  /**
68	   * Retrieve memory by ID (from SQLite primary)
69	   */
70	  async retrieve(id: string): Promise<Memory | undefined> {
71	    return this.sqliteBackend.retrieve(id);
72	  }
73	
74	  /**
75	   * Update memory in both backends
76	   */
77	  async update(memory: Memory): Promise<void> {
78	    await this.sqliteBackend.update(memory);
79	
80	    if (memory.embedding && memory.embedding.length > 0) {
81	      await this.agentDbBackend.update(memory);
82	    }
83	  }
84	
85	  /**
86	   * Delete memory from both backends
87	   */
88	  async delete(id: string): Promise<void> {
89	    await Promise.all([
90	      this.sqliteBackend.delete(id),
91	      this.agentDbBackend.delete(id)
92	    ]);
93	  }
94	
95	  /**
96	   * Query memories using SQLite
97	   */
98	  async query(query: MemoryQuery): Promise<Memory[]> {
99	    return this.sqliteBackend.query(query);
100	  }
101	
102	  /**
103	   * Vector search using AgentDB (150x-12,500x faster with HNSW)
104	   */
105	  async vectorSearch(embedding: number[], k: number = 10): Promise<MemorySearchResult[]> {
106	    return this.agentDbBackend.vectorSearch(embedding, k);
107	  }
108	
109	  /**
110	   * Clear all memories for an agent
111	   */
112	  async clearAgent(agentId: string): Promise<void> {
113	    await Promise.all([
114	      this.sqliteBackend.clearAgent(agentId),
115	      this.agentDbBackend.clearAgent(agentId)
116	    ]);
117	  }
118	
119	  /**
120	   * Hybrid search: combine SQL filtering with vector similarity
121	   */
122	  async hybridSearch(
123	    query: MemoryQuery,
124	    embedding?: number[],
125	    k: number = 10
126	  ): Promise<MemorySearchResult[]> {
127	    if (!embedding) {
128	      // No embedding, fall back to SQL query
129	      const results = await this.query(query);
130	      return results.map(m => ({ ...m, similarity: 1.0 }));
131	    }
132	
133	    // Get vector search results
134	    const vectorResults = await this.vectorSearch(embedding, k * 2);
135	
136	    // Filter by query criteria
137	    let filtered = vectorResults;
138	
139	    if (query.agentId) {
140	      filtered = filtered.filter(m => m.agentId === query.agentId);
141	    }
142	    if (query.type) {
143	      filtered = filtered.filter(m => m.type === query.type);
144	    }
145	    if (query.timeRange) {
146	      filtered = filtered.filter(
147	        m => m.timestamp >= query.timeRange!.start && m.timestamp <= query.timeRange!.end
148	      );
149	    }
150	    if (query.metadata) {
151	      filtered = filtered.filter(m => {
152	        if (!m.metadata) return false;
153	        return Object.entries(query.metadata!).every(
154	          ([key, value]) => m.metadata![key] === value
155	        );
156	      });
157	    }
158	
159	    return filtered.slice(0, k);
160	  }
161	
162	  /**
163	   * Get backend statistics
164	   */
165	  getStats(): { sqlite: number; agentdb: number } {
166	    return {
167	      sqlite: this.sqliteBackend.getCount(),
168	      agentdb: 0 // AgentDB doesn't expose count directly
169	    };
170	  }
171	}
172	
173	export { HybridBackend as default };
