1	/**
2	 * WorkflowEngine
3	 *
4	 * Executes and manages workflows with support for dependencies, parallelism,
5	 * rollback, and distributed execution.
6	 */
7	
8	import { EventEmitter } from 'events';
9	import { Task } from '../domain/Task';
10	import type { SwarmCoordinator } from '../../coordination/application/SwarmCoordinator';
11	import type {
12	  MemoryBackend,
13	  PluginManagerInterface,
14	  Task as ITask,
15	  TaskResult,
16	  WorkflowDefinition,
17	  WorkflowResult,
18	  WorkflowState,
19	  WorkflowStatus,
20	  WorkflowMetrics,
21	  WorkflowDebugInfo
22	} from '../../shared/types';
23	
24	export interface WorkflowEngineOptions {
25	  coordinator: SwarmCoordinator;
26	  memoryBackend?: MemoryBackend;
27	  eventBus?: EventEmitter;
28	  pluginManager?: PluginManagerInterface;
29	}
30	
31	interface WorkflowExecution {
32	  id: string;
33	  state: WorkflowState;
34	  promise?: Promise<WorkflowResult>;
35	  resolve?: (result: WorkflowResult) => void;
36	  reject?: (error: Error) => void;
37	  executionOrder: string[];
38	  taskTimings: Record<string, { start: number; end: number; duration: number }>;
39	  eventLog: Array<{ timestamp: number; event: string; data: unknown }>;
40	  memorySnapshots: Array<{ timestamp: number; snapshot: Record<string, unknown> }>;
41	}
42	
43	export class WorkflowEngine {
44	  private coordinator: SwarmCoordinator;
45	  private memoryBackend?: MemoryBackend;
46	  private eventBus: EventEmitter;
47	  private pluginManager?: PluginManagerInterface;
48	  private workflows: Map<string, WorkflowExecution>;
49	  private initialized: boolean = false;
50	
51	  constructor(options: WorkflowEngineOptions) {
52	    this.coordinator = options.coordinator;
53	    this.memoryBackend = options.memoryBackend;
54	    this.eventBus = options.eventBus || new EventEmitter();
55	    this.pluginManager = options.pluginManager;
56	    this.workflows = new Map();
57	  }
58	
59	  /**
60	   * Initialize the workflow engine
61	   */
62	  async initialize(): Promise<void> {
63	    if (this.initialized) return;
64	    this.initialized = true;
65	  }
66	
67	  /**
68	   * Shutdown the workflow engine
69	   */
70	  async shutdown(): Promise<void> {
71	    // Cancel all running workflows
72	    for (const [id, execution] of this.workflows.entries()) {
73	      if (execution.state.status === 'in-progress') {
74	        execution.state.status = 'cancelled';
75	        if (execution.reject) {
76	          execution.reject(new Error('Workflow engine shutdown'));
77	        }
78	      }
79	    }
80	    this.workflows.clear();
81	    this.initialized = false;
82	  }
83	
84	  /**
85	   * Execute a single task
86	   */
87	  async executeTask(task: ITask, agentId: string): Promise<TaskResult> {
88	    // Store task start
89	    if (this.memoryBackend) {
90	      await this.memoryBackend.store({
91	        id: `task-start-${task.id}`,
92	        agentId,
93	        content: `Task ${task.id} started`,
94	        type: 'task-start',
95	        timestamp: Date.now(),
96	        metadata: { taskId: task.id, agentId }
97	      });
98	    }
99	
100	    const result = await this.coordinator.executeTask(agentId, task);
101	
102	    // Store task completion
103	    if (this.memoryBackend) {
104	      await this.memoryBackend.store({
105	        id: `task-complete-${task.id}`,
106	        agentId,
107	        content: `Task ${task.id} ${result.status}`,
108	        type: 'task-complete',
109	        timestamp: Date.now(),
110	        metadata: { taskId: task.id, agentId, status: result.status, duration: result.duration }
111	      });
112	    }
113	
114	    return result;
115	  }
116	
117	  /**
118	   * Execute a workflow
119	   */
120	  async executeWorkflow(workflow: WorkflowDefinition): Promise<WorkflowResult> {
121	    const execution = this.createExecution(workflow);
122	    this.workflows.set(workflow.id, execution);
123	
124	    // Invoke before execute hook
125	    if (this.pluginManager) {
126	      await this.pluginManager.invokeExtensionPoint('workflow.beforeExecute', workflow);
127	    }
128	
129	    this.eventBus.emit('workflow:started', {
130	      workflowId: workflow.id,
131	      taskCount: workflow.tasks.length
132	    });
133	
134	    execution.eventLog.push({
135	      timestamp: Date.now(),
136	      event: 'workflow:started',
137	      data: { workflowId: workflow.id }
138	    });
139	
140	    try {
141	      const result = await this.runWorkflow(execution, workflow);
142	
143	      // Invoke after execute hook
144	      if (this.pluginManager) {
145	        await this.pluginManager.invokeExtensionPoint('workflow.afterExecute', result);
146	      }
147	
148	      this.eventBus.emit('workflow:completed', {
149	        workflowId: workflow.id,
150	        result
151	      });
152	
153	      return result;
154	    } catch (error) {
155	      const failedResult: WorkflowResult = {
156	        id: workflow.id,
157	        status: 'failed',
158	        tasksCompleted: execution.state.completedTasks.length,
159	        errors: [error instanceof Error ? error : new Error(String(error))],
160	        executionOrder: execution.executionOrder
161	      };
162	
163	      // Handle rollback if configured
164	      if (workflow.rollbackOnFailure) {
165	        await this.rollbackWorkflow(execution, workflow);
166	      }
167	
168	      this.eventBus.emit('workflow:failed', {
169	        workflowId: workflow.id,
170	        error
171	      });
172	
173	      return failedResult;
174	    }
