367	  private async runWorkflow(
368	    execution: WorkflowExecution,
369	    workflow: WorkflowDefinition
370	  ): Promise<WorkflowResult> {
371	    const tasks = workflow.tasks.map(t => new Task(t));
372	    const completedTasks = new Set<string>();
373	    const errors: Error[] = [];
374	
375	    // Resolve execution order
376	    const orderedTasks = Task.resolveExecutionOrder(tasks);
377	
378	    for (const task of orderedTasks) {
379	      // Check if paused
380	      while (execution.state.status === 'paused') {
381	        await new Promise(resolve => setTimeout(resolve, 100));
382	      }
383	
384	      if (execution.state.status === 'cancelled') {
385	        break;
386	      }
387	
388	      execution.state.currentTask = task.id;
389	
390	      const startTime = Date.now();
391	
392	      try {
393	        // Handle nested workflows
394	        if (task.isWorkflow() && task.workflow) {
395	          const nestedResult = await this.executeWorkflow(task.workflow);
396	          if (nestedResult.status === 'failed') {
397	            throw new Error(`Nested workflow failed`);
398	          }
399	        } else {
400	          // Get assigned agent or distribute
401	          let agentId = task.assignedTo;
402	          if (!agentId) {
403	            const agents = await this.coordinator.listAgents();
404	            const suitable = agents.find(a => a.canExecute(task.type));
405	            agentId = suitable?.id;
406	          }
407	
408	          if (!agentId) {
409	            throw new Error(`No agent available for task ${task.id}`);
410	          }
411	
412	          const result = await this.executeTask(task, agentId);
413	          if (result.status === 'failed') {
414	            throw new Error(result.error || 'Task execution failed');
415	          }
416	        }
417	
418	        const endTime = Date.now();
419	        execution.taskTimings[task.id] = {
420	          start: startTime,
421	          end: endTime,
422	          duration: endTime - startTime
423	        };
424	
425	        completedTasks.add(task.id);
426	        execution.state.completedTasks.push(task.id);
427	        execution.executionOrder.push(task.id);
428	
429	        this.eventBus.emit('workflow:taskComplete', {
430	          workflowId: workflow.id,
431	          taskId: task.id
432	        });
433	
434	        execution.eventLog.push({
435	          timestamp: endTime,
436	          event: 'task:completed',
437	          data: { taskId: task.id, duration: endTime - startTime }
438	        });
439	      } catch (error) {
440	        errors.push(error instanceof Error ? error : new Error(String(error)));
441	
442	        if (workflow.rollbackOnFailure) {
443	          throw error; // Let outer handler deal with rollback
444	        }
445	      }
446	    }
447	
448	    execution.state.status = errors.length > 0 ? 'failed' : 'completed';
449	    execution.state.completedAt = Date.now();
450	
451	    return {
452	      id: workflow.id,
453	      status: errors.length > 0 ? 'failed' : 'completed',
454	      tasksCompleted: completedTasks.size,
455	      errors,
456	      executionOrder: execution.executionOrder,
457	      duration: execution.state.completedAt - (execution.state.startedAt || 0)
458	    };
459	  }
