461	  private async rollbackWorkflow(
462	    execution: WorkflowExecution,
463	    workflow: WorkflowDefinition
464	  ): Promise<void> {
465	    // Rollback in reverse order
466	    const completedTaskIds = [...execution.state.completedTasks].reverse();
467	
468	    for (const taskId of completedTaskIds) {
469	      const task = workflow.tasks.find(t => t.id === taskId);
470	      if (task?.onRollback) {
471	        try {
472	          await task.onRollback();
473	          execution.eventLog.push({
474	            timestamp: Date.now(),
475	            event: 'task:rolledback',
476	            data: { taskId }
477	          });
478	        } catch (error) {
479	          // Log but continue rollback
480	          execution.eventLog.push({
481	            timestamp: Date.now(),
482	            event: 'rollback:error',
483	            data: { taskId, error: String(error) }
484	          });
485	        }
486	      }
487	    }
488	  }
489	}
